  ('quant', 'LCM & HCF', 2, 'Three bells ring at intervals of 4, 30 and 45 minutes. They ring together at 8:00 AM. When will they next ring together?', array['11:00 AM', '2:00 PM', '9:30 AM', '9:19 AM'], 0, 'They ring together every LCM(4, 30, 45) = 180 minutes. 8:00 AM + 180 minutes = 11:00 AM.', 40, 'bells_lcm', null, null, null),
  ('quant', 'LCM & HCF', 2, 'Three bells ring at intervals of 4, 5 and 30 minutes. They ring together at 10:00 AM. When will they next ring together?', array['10:30 AM', '11:00 AM', '10:39 AM', '12:00 PM'], 1, 'They ring together every LCM(4, 5, 30) = 60 minutes. 10:00 AM + 60 minutes = 11:00 AM.', 40, 'bells_lcm', null, null, null),
