  ('verbal', 'Antonyms', 1, 'Choose the word opposite in meaning to HUMBLE.', array['Polite', 'Modest', 'Simple', 'Arrogant'], 3, 'Humble means modest; arrogant means having too high an opinion of oneself.', 25, 'curated_antonyms', null, null, null),
  ('verbal', 'Antonyms', 2, 'Choose the word opposite in meaning to SCARCITY.', array['Lack', 'Shortage', 'Poverty', 'Abundance'], 3, 'Scarcity means too little of something; abundance means plenty.', 25, 'curated_antonyms', null, null, null),
