  ('verbal', 'Antonyms', 2, 'Choose the word opposite in meaning to VOLUNTARY.', array['Willing', 'Compulsory', 'Optional', 'Free'], 1, 'Voluntary is done by choice; compulsory is required.', 25, 'curated_antonyms', null, null, null),
